import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry sigmoid_fwd(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 numel
)
{
    .reg .pred   %p_done;
    .reg .b32    %rIdx, %rBlk, %rThd, %rBDim, %rGrid, %rStride, %rNum;
    .reg .b64    %in, %out, %addr_in, %addr_out, %off;
    .reg .f32    %x, %negx, %t, %e, %den, %y, %log2e;

    // Load parameters
    ld.param.u64 %in,  [in_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.u32 %rNum, [numel];

    // Convert to global space (generic -> global)
    cvta.to.global.u64 %in,  %in;
    cvta.to.global.u64 %out, %out;

    // Compute thread index and stride
    mov.u32 %rThd,  %tid.x;
    mov.u32 %rBlk,  %ctaid.x;
    mov.u32 %rBDim, %ntid.x;
    mad.lo.u32 %rIdx, %rBlk, %rBDim, %rThd;   // idx = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %rGrid, %nctaid.x;                // gridDim.x
    mul.lo.u32 %rStride, %rBDim, %rGrid;      // stride = blockDim.x * gridDim.x

    // Constant log2(e)
    mov.f32 %log2e, 1.44269502;

LOOP:
    setp.ge.u32 %p_done, %rIdx, %rNum;
    @%p_done bra DONE;

    // Load x
    mul.wide.u32 %off, %rIdx, 4;
    add.s64 %addr_in, %in, %off;
    ld.global.f32 %x, [%addr_in];

    // y = 1 / (1 + exp(-x)) using exp(-x) = 2^{(-x)*log2(e)}
    neg.f32 %negx, %x;
    mul.f32 %t, %negx, %log2e;
    ex2.approx.f32 %e, %t;
    add.f32 %den, %e, 1.0;
    rcp.approx.f32 %y, %den;

    // Store y
    add.s64 %addr_out, %out, %off;
    st.global.f32 [%addr_out], %y;

    add.u32 %rIdx, %rIdx, %rStride;
    bra LOOP;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("sigmoid_fwd")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor.")
        if x.dtype != torch.float32:
            raise RuntimeError("Input dtype must be torch.float32.")
        if not x.is_contiguous():
            raise RuntimeError("Input must be contiguous.")

        y = torch.empty_like(x)
        numel = x.numel()
        if numel == 0:
            return y

        module = _get_ptx_module()

        block_x = 256
        grid_x = (numel + block_x - 1) // block_x
        # Avoid zero grid in pathological cases
        grid_x = max(1, grid_x)

        module.launch(
            "sigmoid_fwd",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, y, i32(numel)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

